(async()=>{
 const {plusMods,installSample}=await import('/plus/mods/manager.js');const {registerModsTab}=await import('/plus/tabs/mods.js');
 const {mountPlus}=await import('/plus/plus.js');const plus=mountPlus();await plus.ready;await plus.setSetting('original',false);await installSample();
 const dax=await import('/engine/dax.js'),pic=await import('/engine/pictures.js'),{decodePicture}=await import('/plus/pedia/pictures.js');
 const bytes=await dax.fetchFile('PIC3.DAX'),dir=dax.readDir(bytes),originals=new Map();
 for(const id of [1,29,41]){const e=dir.entries.find(e=>e.id===id);originals.set(id,dax.DaxRleDecode(bytes.subarray(dir.dataStart+e.ofs,dir.dataStart+e.ofs+e.comp),e.comp,e.raw));}
 const saved=pic.state.display.pix.slice(),canvas=document.getElementById('screen');
 const draw=async useMods=>{const d=pic.state.display;d.pix.fill(0);let i=0;for(const [id,raw]of originals){const override=useMods?await plusMods.resolve('PIC3',id,raw):null;const image=decodePicture(override||raw,{animation:true,xor:true});const p=pic.AllocPicture(image.height,image.width/8,1,0);p.px.set(image.pixels);pic.PutPicture(1+i*11,4,p);i++;}d.touch();d.present();return canvas.toDataURL();};
 await plusMods.enable('sample-recolour',false);const baseline=await draw(false);
 registerModsTab(plus);plus.open();plus.selectTab('mods');await new Promise(r=>setTimeout(r,50));if(!document.getElementById('por-plus-content').textContent.includes('Sample PIC recolour'))throw Error('Mods UI missing');plus.close();
 window.__modsTest={plusMods,plus,dax,pic,originals,saved,draw,baseline};return {pass:true,baseline:true,targets:3};
})()

(async()=>{const t=window.__modsTest;await t.plusMods.enable('sample-recolour',true);const changed=[];let engineHook=true;
 for(const [id,raw]of t.originals){const override=await t.plusMods.resolve('PIC3',id,raw);if(!override || override.every((b,i)=>b===raw[i]))throw Error('PIC not recoloured: '+id);changed.push(id);const loaded=await t.dax.LoadDaxRecord('PIC3','.dax',id);if(loaded.every((b,i)=>b===raw[i]))engineHook=false;}
 const atlas=await t.draw(true);if(atlas===t.baseline)throw Error('Atlas unchanged');return {pass:true,recoloured:changed,engineLoaderHook:engineHook};})()

(async()=>{const t=window.__modsTest;await t.plusMods.enable('sample-recolour',false);if(await t.draw(true)!==t.baseline)throw Error('Disabled mod changed original pixels');
 await t.plusMods.enable('sample-recolour',true);await t.plus.setSetting('original',true);for(const [id,raw]of t.originals)if(await t.plusMods.resolve('PIC3',id,raw)!==null)throw Error('Master bypass failed');if(await t.draw(true)!==t.baseline)throw Error('Original mode changed pixels');
 await t.plus.setSetting('original',false);await t.plusMods.enable('sample-recolour',false);return {pass:true,disabledPixelsEqual:true,originalModePixelsEqual:true};})()
